CREATE TABLE public.cook_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE, nombre text NOT NULL CHECK (length(nombre) BETWEEN 2 AND 100), distrito text NOT NULL CHECK(length(distrito) BETWEEN 2 AND 100), descripcion text NOT NULL DEFAULT '' CHECK(length(descripcion)<=1000), foto text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.cook_profiles TO authenticated; GRANT ALL ON public.cook_profiles TO service_role;
ALTER TABLE public.cook_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY cook_read ON public.cook_profiles FOR SELECT TO authenticated USING(true);
CREATE POLICY cook_insert ON public.cook_profiles FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY cook_update ON public.cook_profiles FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.cook_certificates (cook_id uuid PRIMARY KEY REFERENCES public.cook_profiles(id), user_id uuid NOT NULL, nombre text NOT NULL, contenido text NOT NULL);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.cook_certificates TO authenticated; GRANT ALL ON public.cook_certificates TO service_role;
ALTER TABLE public.cook_certificates ENABLE ROW LEVEL SECURITY;
CREATE POLICY certificate_owner ON public.cook_certificates FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.cook_profiles c WHERE c.id=cook_id AND c.user_id=auth.uid()));
CREATE TABLE public.service_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_id uuid NOT NULL, cook_id uuid NOT NULL REFERENCES public.cook_profiles(id), duracion text NOT NULL CHECK(duracion IN ('2dias','semana')), personas text NOT NULL CHECK(personas IN ('1','2','3-4','5+')), total numeric NOT NULL, fecha date NOT NULL, distrito text NOT NULL CHECK(length(distrito) BETWEEN 2 AND 100), detalles text NOT NULL DEFAULT '' CHECK(length(detalles)<=2000), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','declined','awaiting_confirmation','completed','cancelled')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.service_requests TO authenticated; GRANT ALL ON public.service_requests TO service_role;
ALTER TABLE public.service_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY request_participants ON public.service_requests FOR SELECT TO authenticated USING(client_id=auth.uid() OR EXISTS(SELECT 1 FROM public.cook_profiles c WHERE c.id=cook_id AND c.user_id=auth.uid()));
CREATE TABLE public.service_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.service_requests(id), sender_id uuid NOT NULL, body text NOT NULL CHECK(length(trim(body)) BETWEEN 1 AND 2000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.service_messages TO authenticated; GRANT ALL ON public.service_messages TO service_role;
ALTER TABLE public.service_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY message_read ON public.service_messages FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.service_requests r WHERE r.id=request_id));
CREATE POLICY message_send ON public.service_messages FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND EXISTS(SELECT 1 FROM public.service_requests r WHERE r.id=request_id AND r.status IN ('pending','accepted','awaiting_confirmation')));
CREATE TABLE public.cook_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL UNIQUE REFERENCES public.service_requests(id), cook_id uuid NOT NULL REFERENCES public.cook_profiles(id), client_id uuid NOT NULL, estrellas integer NOT NULL CHECK(estrellas BETWEEN 1 AND 5), mensaje text NOT NULL DEFAULT '' CHECK(length(mensaje)<=1000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.cook_reviews TO authenticated; GRANT ALL ON public.cook_reviews TO service_role;
ALTER TABLE public.cook_reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY review_read ON public.cook_reviews FOR SELECT TO authenticated USING(true);
CREATE POLICY review_verified ON public.cook_reviews FOR INSERT TO authenticated WITH CHECK(client_id=auth.uid() AND EXISTS(SELECT 1 FROM public.service_requests r WHERE r.id=request_id AND r.client_id=auth.uid() AND r.cook_id=cook_reviews.cook_id AND r.status='completed'));
CREATE FUNCTION public.public_cooks() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('id',c.id,'nombre',c.nombre,'distrito',c.distrito,'descripcion',c.descripcion,'foto',c.foto,'certificado',EXISTS(SELECT 1 FROM cook_certificates cc WHERE cc.cook_id=c.id),'promedio',(SELECT round(avg(estrellas),1) FROM cook_reviews v WHERE v.cook_id=c.id),'cantidad',(SELECT count(*) FROM cook_reviews v WHERE v.cook_id=c.id),'resenas',(SELECT coalesce(jsonb_agg(jsonb_build_object('estrellas',v.estrellas,'mensaje',v.mensaje)), '[]'::jsonb) FROM cook_reviews v WHERE v.cook_id=c.id))), '[]'::jsonb) FROM cook_profiles c $$;
REVOKE ALL ON FUNCTION public.public_cooks() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.public_cooks() TO anon,authenticated,service_role;
CREATE FUNCTION public.create_service(p_cook uuid,p_duracion text,p_personas text,p_fecha date,p_distrito text,p_detalles text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; amount numeric; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Debe iniciar sesión'; END IF; IF NOT EXISTS(SELECT 1 FROM cook_profiles WHERE id=p_cook AND user_id<>auth.uid()) THEN RAISE EXCEPTION 'Cocinera no disponible'; END IF; IF p_fecha < (now() AT TIME ZONE 'America/Lima')::date THEN RAISE EXCEPTION 'Fecha inválida'; END IF; amount := (CASE p_duracion WHEN '2dias' THEN 8 WHEN 'semana' THEN 20 ELSE NULL END) * (CASE p_personas WHEN '1' THEN 15 WHEN '2' THEN 18 WHEN '3-4' THEN 22 WHEN '5+' THEN 28 ELSE NULL END); IF amount IS NULL THEN RAISE EXCEPTION 'Paquete inválido'; END IF; INSERT INTO service_requests(client_id,cook_id,duracion,personas,total,fecha,distrito,detalles) VALUES(auth.uid(),p_cook,p_duracion,p_personas,amount,p_fecha,trim(p_distrito),p_detalles) RETURNING id INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.create_service(uuid,text,text,date,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_service(uuid,text,text,date,text,text) TO authenticated;
CREATE FUNCTION public.change_service(p_id uuid,p_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r service_requests; is_cook boolean; BEGIN SELECT * INTO r FROM service_requests WHERE id=p_id FOR UPDATE; IF NOT FOUND OR auth.uid() IS NULL THEN RAISE EXCEPTION 'Solicitud no disponible'; END IF; SELECT EXISTS(SELECT 1 FROM cook_profiles WHERE id=r.cook_id AND user_id=auth.uid()) INTO is_cook; IF NOT ((is_cook AND r.status='pending' AND p_status IN ('accepted','declined')) OR (is_cook AND r.status='accepted' AND p_status='awaiting_confirmation') OR (r.client_id=auth.uid() AND r.status='awaiting_confirmation' AND p_status='completed') OR (r.client_id=auth.uid() AND r.status IN ('pending','accepted') AND p_status='cancelled')) THEN RAISE EXCEPTION 'Cambio no permitido'; END IF; UPDATE service_requests SET status=p_status WHERE id=p_id; END $$;
REVOKE ALL ON FUNCTION public.change_service(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.change_service(uuid,text) TO authenticated;
CREATE INDEX request_client_idx ON public.service_requests(client_id); CREATE INDEX request_cook_idx ON public.service_requests(cook_id); CREATE INDEX message_request_idx ON public.service_messages(request_id,created_at); CREATE INDEX review_cook_idx ON public.cook_reviews(cook_id);
ALTER PUBLICATION supabase_realtime ADD TABLE public.service_messages;
ALTER PUBLICATION supabase_realtime ADD TABLE public.service_requests;